144	func (s *gitRefsStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
145		if err := ctx.Err(); err != nil {
146			return err //nolint:wrapcheck // Propagating context cancellation
147		}
148		if opts.CheckpointID.IsEmpty() {
149			return errors.New("invalid update options: checkpoint ID is required")
150		}
151	
152		refName, err := s.prepareRefForBackfill(ctx, opts.CheckpointID)
153		if err != nil {
154			return err
155		}
156		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
157		commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
158		_, err = RunRefTransaction(ctx, s.repo, refName, func(parentHash plumbing.Hash) (plumbing.Hash, bool, error) {
159			existing, err := s.checkpointTreeAt(parentHash, opts.CheckpointID)
160			if err != nil {
161				return plumbing.ZeroHash, false, err
162			}
163			checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, "")
164			if err != nil {
165				return plumbing.ZeroHash, false, err
166			}
167			commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
168			return commitHash, true, err
