2170	// resolveSessionsBranchTrees resolves each read candidate's ref and loads its root
2171	// tree, deduplicated by commit. Purely local: no network. The returned error is
2172	// advisory — the first resolution failure — and is only fatal to the caller when
2173	// no tree resolved at all.
2174	// metadataTree is one resolved read-candidate tree together with the ref it
2175	// came from, so consumers can report WHICH tier served a read — the risk the
2176	// chain carries is a wrong-tier read going unnoticed, and "silently" is the
2177	// part observability removes.
2178	type metadataTree struct {
2179		tree *object.Tree
2180		ref  plumbing.ReferenceName
2181	}
2182	
2183	// local reports whether this tree came from the local read ref rather than a
2184	// remote-tracking tier.
2185	func (m metadataTree) local(readRef plumbing.ReferenceName) bool {
2186		return m.ref == readRef
2187	}
2188	
2189	func (s *GitStore) resolveSessionsBranchTrees() ([]metadataTree, error) {
2190		refNames := []plumbing.ReferenceName{s.refs.Read}
2191		if s.refs.ReadBootstrappableFromRemote() {
2192			remotes := s.readRemotes
2193			if len(remotes) == 0 {
2194				remotes = []string{"origin"}
2195			}
2196			for _, remoteName := range remotes {
2197				refNames = append(refNames, plumbing.NewRemoteReferenceName(remoteName, s.refs.Primary.Short()))
2198			}
2199		}
2200	
2201		trees := make([]metadataTree, 0, len(refNames))
2202		kept := make([]*object.Commit, 0, len(refNames))
2203		seen := make(map[plumbing.Hash]struct{}, len(refNames))
2204		var firstErr error
2205		for _, refName := range refNames {
2206			ref, err := s.repo.Reference(refName, true)
2207			if err != nil {
2208				if firstErr == nil {
2209					firstErr = err
2210				}
2211				continue
2212			}
2213			if _, ok := seen[ref.Hash()]; ok {
2214				continue
2215			}
2216			commit, err := s.repo.CommitObject(ref.Hash())
2217			if err != nil {
2218				if firstErr == nil {
2219					firstErr = fmt.Errorf("failed to get commit object for %s: %w", refName, err)
2220				}
2221				continue
2222			}
2223			// A candidate whose commit is an ancestor of an already-kept tree
2224			// contributes nothing: every checkpoint in it is in the descendant.
2225			// This is the common shape — the local branch ahead of a tracking
2226			// ref — and skipping it saves consumers a full duplicate shard walk
2227			// on every List. Best-effort: an ancestry-check error keeps the tree
2228			// (a duplicate walk is cheaper than a missed checkpoint).

